### CLI example

```ts
#!/usr/bin/env node
import { globby } from "globby";
import fs from "node:fs/promises";
import path from "node:path";
import crypto from "node:crypto";

const ALLOWLIST = [
  "**/package.json",
  "**/package-lock.json",
  "**/pnpm-lock.yaml",
  "**/yarn.lock",
  "**/LICENSE*",
  "**/NOTICE*",
  "**/*.license",
  "**/*.lic"
];

function hash(content: string) {
  return crypto.createHash("sha256").update(content).digest("hex");
}

async function main() {
  const root = process.argv.includes("--path")
    ? path.resolve(process.argv[process.argv.indexOf("--path") + 1])
    : process.cwd();

  const files = await globby(ALLOWLIST, {
    cwd: root,
    dot: false,
    followSymbolicLinks: false
  });

  const report = [];
  for (const file of files) {
    const full = path.join(root, file);
    const content = await fs.readFile(full, "utf8");
    report.push({
      file,
      sha256: hash(content),
      bytes: Buffer.byteLength(content)
    });
  }

  console.log(JSON.stringify({ root, files: report }, null, 2));

  // Only send if explicitly enabled
  if (process.env.LICENSE_COMPLIANCE_UPLOAD === "true") {
    // POST report to your API here
  }
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});
```

