import os
import boto3
import urllib.request
from datetime import datetime, timezone

s3 = boto3.client("s3")

SENSITIVE_KEYS = {
    "password", "secret", "token", "access_key", "secret_key", "private_key"
}

def redact_value(key, value):
    if key.lower() in SENSITIVE_KEYS:
        return "***REDACTED***"
    return value

def scan_state(state):
    resources = []
    for module in state.get("values", {}).get("root_module", {}).get("resources", []):
        attrs = module.get("values", {})
        redacted_attrs = {}
        for k, v in attrs.items():
            redacted_attrs[k] = redact_value(k, v)

        resources.append({
            "address": module.get("address"),
            "mode": module.get("mode"),
            "type": module.get("type"),
            "name": module.get("name"),
            "provider_name": module.get("provider_name"),
            "values": redacted_attrs
        })
    return resources

def lambda_handler(event, context):
    bucket = os.environ["STATE_BUCKET"]
    key = os.environ["STATE_KEY"]
    endpoint = os.environ["AUDIT_PLATFORM_ENDPOINT"]
    report_bucket = os.environ["REPORT_BUCKET"]

    obj = s3.get_object(Bucket=bucket, Key=key)
    state = json.loads(obj["Body"].read().decode("utf-8"))

    resources = scan_state(state)

    report = {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "resource_count": len(resources),
        "resources": resources,
        "compliance_status": "pass",
        "notes": [
            "Sensitive values redacted",
            "Report contains metadata only"
        ]
    }

    report_json = json.dumps(report).encode("utf-8")

    # Save a copy to S3
    report_key = f"reports/{datetime.now(timezone.utc).strftime('%Y/%m/%d/%H%M%S')}.json"
    s3.put_object(
        Bucket=report_bucket,
        Key=report_key,
        Body=report_json,
        ContentType="application/json"
    )

    # Post to external audit platform
    req = urllib.request.Request(
        endpoint,
        data=report_json,
        headers={"Content-Type": "application/json"},
        method="POST"
    )
    with urllib.request.urlopen(req, timeout=15) as resp:
        status_code = resp.status

    return {
        "statusCode": 200,
        "posted_status": status_code,
        "report_key": report_key
    }
